import{_ as t,a as r}from"./chunks/78ee3e6c1d6fe4228a7a.DEtd0Mqx.js";import{_ as o,C as l,o as s,c as i,j as e,a as n,E as h,a5 as m}from"./chunks/framework.DNkHA0lr.js";const w=JSON.parse('{"title":"如何创造你人生中最伟大的翻身仗","description":"","frontmatter":{"title":"如何创造你人生中最伟大的翻身仗","originalTitle":"How To Make The Greatest Comeback Of Your Life","date":"2024-12-07","originalUrl":"https://thedankoe.com/letters/how-to-make-the-greatest-comeback-of-your-life/","minutes":12,"sourceHash":"6f93958a75306cc6febb87b63ea05ff2d8b5e1ae246daaa299591b2675173dde","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-make-the-greatest-comeback-of-your-life/"}]]},"headers":[],"relativePath":"letters/how-to-make-the-greatest-comeback-of-your-life.md","filePath":"letters/how-to-make-the-greatest-comeback-of-your-life.md"}'),c={name:"letters/how-to-make-the-greatest-comeback-of-your-life.md"};function d(f,p,b,k,u,_){const a=l("ArticleMeta");return s(),i("div",null,[p[0]||(p[0]=e("h1",{id:"如何创造你人生中最伟大的翻身仗",tabindex:"-1"},[n("如何创造你人生中最伟大的翻身仗 "),e("a",{class:"header-anchor",href:"#如何创造你人生中最伟大的翻身仗","aria-label":'Permalink to "如何创造你人生中最伟大的翻身仗"'},"​")],-1)),h(a),p[1]||(p[1]=m('<p><a href="https://www.youtube.com/embed/cG-brqeMrBw?si=2V_BNEdnak5i9E2U" target="_blank" rel="noreferrer">观看原文视频</a></p><p>大多数人都感觉被困住了。</p><p>他们的思维感觉狭窄而渺小。</p><p>他们无法逃离那种重复性负面思维的泡泡。</p><p>他们对自己人生要做什么缺乏清晰认知。</p><p>他们不知道自己想要投入的那“一件事”是什么，因为自助领域的每个人都在朝他们大喊要专注于“一件事”，但那完全没有抓住重点。</p><p>（你不该专注于一件事。你该专注于一个使命，而这个使命会迫使你专注于许多事情。专注于一件事是让自己依赖那件事、永远无法适应的必然途径。）</p><p>他们有一些随机的野心，比如在社交媒体上获得一些粉丝，开始某个他们在网上偶然发现的随机生意，试图“搞到一个女友”来结束孤独，或者任何其他能让他们抓住的东西，来获得人生方向感。而那些特定的东西，比如创业，看起来是值得的，因为至少那是一条与我们这个搞砸了的文化为他们设定的死胡同不同的道路。</p><p>难怪大多数人根本无法开始。</p><p>难怪他们对自己做的每件事都心存质疑。</p><p>难怪大多数人很难实现任何有价值的东西。</p><p>于是他们慢慢开始接受，也许自己注定就是平庸的。也许你注定要醒来，按四次贪睡键，遛狗，通勤上班，假装喜欢那里的人，假装在乎自己的任务，通勤回家，和另一半争吵，看电视，昏睡过去，然后重复。</p><p>但有些东西缺失了。</p><p>你正试图用一个被训练成奴仆的思维去实现自由。</p><p>那就像试图把一个方块塞进一个圆孔里。</p><p>这永远不会成功。</p><h2 id="如何弄清楚你在人生中想要什么" tabindex="-1">如何弄清楚你在人生中想要什么 <a class="header-anchor" href="#如何弄清楚你在人生中想要什么" aria-label="Permalink to &quot;如何弄清楚你在人生中想要什么&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>人类天生就是通才。</p><p>人类会 <em>制造工具</em> 来适应不同的细分领域和环境。</p><p>而动物，比如撒哈拉的狮子或阿拉斯加的北极熊，如果被扔进一个不同的细分领域，就无法生存。</p><p>这一点不仅限于物理工具。</p><p>人类发明了心智工具，比如语言、文化、概念、宗教和故事，以便他们能够适应、构建，并获得在任何情境中生存所需的知识和技能。</p><p>这就是让我们独一无二的能力。</p><p>这也是大多数人已经失去的能力。</p><p>你看，作为孩子，我们喜欢冒险。我们喜欢探索。我们喜欢弄明白事情。我们犯错并从中学习。 <em>我们会去摸火。</em></p><p>但后来，我们的学习不再关乎真正的错误。</p><p>它开始变成关于父母和老师不喜欢我们身上的哪些特质。他们觉得烦人或不文明的特质。他们认为不会带来那种被灌输为唯一真正道路的成功的特质，而他们从未打开心智去发现，从来就不存在“唯一真正的道路”。</p><p>那所谓的唯一真正的道路又是什么呢？那正是你感到如此迷失、不堪重负、焦虑、困惑等等的原因。</p><p>那条本该是安全稳妥的道路，恰恰是完全相反的。</p><p>你被扔到一个被政府训练出来的“专家”面前，而这个专家又是被其他政府训练出来的专家训练出来的，这些人显然并没有在做你人生中想做的事，每天六个小时，被告知要学什么、该怎么表现，同时不断被推向学位和工作这一地位象征。而如果你理解思维的运作方式，你就会明白，构成你世界观的那些目标——光鲜的学位和高薪工作——决定了你思维的潜在发展和自由度。</p><p>你被训练成了一个专才。</p><p>你被单一地引导去成为医生、律师、艺术家、设计师、工程师，或任何其他自我设限的身份，这种身份塑造并限定了你能够感知和学习的范围。</p><p>你没能培养出 <em>能动性</em>。</p><p>你没能按照自己的意愿去探索、失败、发现和创造，而不是按照别人的意愿。 <em>你没能培养出一个自由个体所具备的那种独特特质。</em></p><p>在过去，自由人被期望依照自己的兴趣去行动。要做到这一点，隐含的意味是他们会在一生中做许多事、学习许多事。最伟大的设计师之所以成为伟大的设计师，是因为他们在生活其他领域的经历，而不是因为他们上了一所地位显赫的学校、然后碰巧比其他人更好地学了同一套课程。</p><p>自由个体与被政府训练出来的专才完全相反，与那种被视为劳动机器、有用工人、奴隶的人完全相反。</p><p>这也与我在<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">《2小时作家》</a>中所教的东西完全相反，因为写作是一种能让你把任何兴趣都转化为创造性工作、而非僵化工作的技能。</p><h3 id="自然的指南针" tabindex="-1">自然的指南针 <a class="header-anchor" href="#自然的指南针" aria-label="Permalink to &quot;自然的指南针&quot;">​</a></h3><p><img src="'+r+'" alt=""></p><p>问题是，你与众不同。</p><p>你自己也意识到了这一点。</p><p>你很善于观察。也许有点安静。害怕说出自己的想法，因为反正他们也不会听。但那种沉默正在杀死你。你试过合群。你试过把自己的未来托付给别人。你试过把金钱、成功等等都当作恶魔来诋毁，因为“你不需要它们也能过上美好的生活”，但你需要的是 <em>去创造</em>。因为那才是你为他人做出贡献、与超越自身的某种东西相连接、并踏上一段独特旅程的方式，这段旅程能终结那种机械化的生活，因为你拥有了让自己摆脱那种机械化生活所需的金钱。</p><p>问题是，你仍在寻找那条“唯一真正的道路”。</p><p>我在这里要告诉你：根本没有那样一条道路。</p><p>如果真有这样一条道路，我们早就该找到了，每个人也早就变得富有、快乐、健康了。但现实并不是这样运作的。事情永远 <em>不会</em> 一直快乐。为什么？因为没有悲伤，快乐就毫无意义。没有胳膊，就没有手的存在。物理、生物、心理和精神层面都包含着这种模式。一件事物不能脱离另一件事物而存在。</p><p>当你去度假时，最终，大概两三周之后，它对你来说就变得平常了。你会感到厌倦。它不再是“假期”了，它成了日常生活。你想回去工作。你想做点什么， <em>任何</em> 事情，只要稍微新鲜、有趣一点。你的思维渴望平衡，但不是那种庸常意义上过着平淡而悲惨生活的平衡。你的思维渴望的是 <em>对比</em>。</p><p>所有这些都是为了说明一件事：</p><p><em>你没有到达你想要的地方，是因为你害怕犯错。</em></p><p>这一点我怎么强调都不够。</p><p>如果有一句唯一真实的话能用来定位你的人生方向，那就是这句。</p><p>错误是自然的指南针。</p><p>如果没有悲伤，快乐就无法存在；同样，没有失败，成功就无法存在。</p><p>这是一条 <em>普遍法则。一种现实的模式。一种自生命最初出现的迹象以来就一直存在的现象，因为“有”不能脱离“无”而存在。</em></p><p>你可以在传统道路上——学校和工作——犯错，但你依然是在朝着一个狭窄的目标努力。那些错误并不会引向一条新的、更好的道路，它们只会让你为自己感到难过。</p><p>当你决定要自由——拒绝那些在你出生时就被分配给你、让你思维狭隘并把你困在这个负面思维泡泡中的目标——你的错误就成了你在黑暗中的光。</p><p>但你不知道自己想要什么。</p><p>这才是问题所在。</p><p>你没有意识到，你永远不会“知道”自己想要什么。它存在于未来。它并不存在。它是想象出来的。生活在变化。你现在想要的东西，明天、后天，或者下一个十年，很可能会完全不同。但你永远不会踏上这个提炼和净化的过程，因为你似乎无法允许自己失败。</p><p>当你意识到自己不想要什么、并朝着相反方向去努力时，你想要的东西就会变得更清晰。既然你从未在自己的道路上犯过错，那你不知道自己想要什么也就不奇怪了。</p><p>我的建议是：</p><p>不经他人许可，去做你想做的事。</p><p>去派对。喝个大醉。开始那个生意。整晚刷手机。做任何你那颗小小的心所渴望的事。真的，因为压抑那些欲望只会让你更加被它们所束缚。</p><p>但这里有个前提。</p><p>你需要能够意识到，什么时候这些事情是一个错误。</p><p>如果你没有每天早上要醒来面对的有意义的责任，那么每晚喝醉就不算是个错误。它没有损害你实现目标的能力。当聚会和酗酒会影响到比聚会和酗酒更重要的事情时，管理它们就会容易得多。既然你的学业和工作都不比这些更重要，那你自然不在乎，照样去做。你需要有自己的目标，而你只能通过对自己所处的状态感到彻底厌烦、并拒绝一切你曾以为是真理的东西，才能生成这些目标。</p><p>你需要从零开始。</p><h2 id="如何创造你人生中最伟大的翻身仗-1" tabindex="-1">如何创造你人生中最伟大的翻身仗 <a class="header-anchor" href="#如何创造你人生中最伟大的翻身仗-1" aria-label="Permalink to &quot;如何创造你人生中最伟大的翻身仗&quot;">​</a></h2><blockquote><p>传统成为我们的安全感，而当心智安全时，它就在腐朽。——J·克里希那穆提</p></blockquote><p>你无法在已知之中做出发现。</p><p>这根本说不通。</p><p>请意识到这一点。</p><p>如果你按照父母和老师植入你脑中的东西去运作，你绝对无法过一种完整、开放、非机械化的生活。当然，你时不时会感到快乐，就像所有人一样，但深层的满足感则是另一回事。大多数人从未体验过那种感觉，因为它对他们来说是未知的，所以他们不愿去寻找它，反而通过告诉你他们作为一个机器人般工作是多么满足，来投射他们自己的不安全感。那些代码行早已刻进了他们的大脑。再说一次，如果你没有一个能让你判断出什么是错误的目标，你就无法感知什么是错误。</p><p>你必须跃入未知，感觉自己仿佛正在溺水，然后学会如何游泳。这才是你学习任何东西的方式，也正因如此，大多数人什么都学不到。他们宁愿一头跳进深水区，抱怨这有多难（仿佛它本该以别的方式存在，或者仿佛困难本身就是坏的、负面的，而不是现实本身），然后把自己无法独立完成任何事、必须别人喂给他们的无能，怪罪到除了自己以外的任何人身上。</p><p>但我到目前为止说的这些废话，都无助于解决一个事实：你此时此刻已经正在溺水了。</p><p>那你该怎么做？你该如何学习？你该如何创造你人生中最伟大的翻身仗？</p><h3 id="对你现在所处的境地感到愤怒" tabindex="-1">对你现在所处的境地感到愤怒 <a class="header-anchor" href="#对你现在所处的境地感到愤怒" aria-label="Permalink to &quot;对你现在所处的境地感到愤怒&quot;">​</a></h3><p>我人生中最好的那些阶段，都是在我彻底厌倦了自己毫无进展之后才到来的。</p><p>我不在乎自己做什么。我只是必须做点什么。我什么都愿意尝试，只为摆脱那种境地。大多数人会称之为绝望，但我会称之为一种渴望学习、成长、进化到下一个层次的思维。</p><p>目标不是立刻找到某一件能缓解你痛苦的事。</p><p>目标是接受你生活方式的一次彻底转变。</p><p>你必须意识到，你所有的行动累积起来，才造成了你现在所处的境地，如果你继续做那些事情，你就会一直停留在原地。唯一真正的改变是行为的改变，所以要向几乎所有你现在紧紧抓着不放、觉得“也没那么糟”的东西说再见。你显然并没有把它们管理得很好。</p><p>你必须对自己所处的境地感到厌恶。</p><p>你必须捏造一个心理上的谷底。</p><p>把你生活中不想要的一切都写下来。</p><p>愚蠢的大脑。虚胖的身体。萎靡的精力。死气沉沉的关系。拒绝它们。</p><p>你可以极度负面,因为负能量比正能量强大得多,但你必须把它引导去锻造一个新的身份。</p><p>我不是在告诉你做一些简单的习惯改变。</p><p>我是在告诉你彻底扳动那个开关。</p><p>因为如果你正确地做这件事……如果你对自己生活中不想要的东西有了绝对的觉知,这个过程并不难。你会不由自主地只想做与你一生所做之事截然相反的事。</p><h3 id="消失三个月" tabindex="-1">消失三个月 <a class="header-anchor" href="#消失三个月" aria-label="Permalink to &quot;消失三个月&quot;">​</a></h3><p>如果你没有愿景,你就是迷失的。</p><p>负能量无处可去,于是被困住,在你的脑海里兴风作浪。心理熵。如果你没有一条有意义的道路、体系或目标去投入那份能量,你就会腐朽。</p><p>但愿景一开始并不清晰。</p><p>它始于一个有依据的猜测。</p><p>你不会对它有信心。</p><p>“我觉得我想试试这个生意。”</p><p>“我觉得我想读这本书。”</p><p>而这就足够开始把能量重新引导向更好的生活,从而将你的大脑朝正向重新编程。</p><p>如果你想规划出自己的愿景并将其分解为可执行的步骤,可以使用我的<a href="https://app.kortex.co/public/document/883d9246-6dde-4794-9f54-92b8ff07d502" target="_blank" rel="noreferrer">简单人生重启规划表</a>,你可以复制并填写它。这会有帮助。</p><p>既然你现在对自己不想要的东西有了残酷的觉知,那就把焦点锁定在你认为自己想要的东西上。</p><p>改善你的身体饮食。改善你的精神饮食。多去散散步。学一项新技能。去健身房。去散步。今天和一个新认识的人聊聊。老天,你正处于未知之中。是的,这会有点不舒服。但这并不能抵消这样一个事实:平庸的生活才是世界上最不舒服的事。一旦你意识到这一点,真正地意识到,其他一切都不算什么了。</p><p>给自己三个月的时间,而不是两周。</p><p>你需要足够的时间投入正确的能量,直到你觉得那件事变得重要为止。就像一首你不喜欢的歌,但听多了,它就变成了你最喜欢的歌。</p><p>第一次去健身房不会好玩。</p><p>第一次学那项技能会很难。</p><p>但当你的技能开始与情境的挑战相匹配时,你会发现这个游戏令人极度沉迷,以至于你除此之外什么都不想做。</p><h3 id="如果它不是一个错误-你什么也没学到" tabindex="-1">如果它不是一个错误,你什么也没学到 <a class="header-anchor" href="#如果它不是一个错误-你什么也没学到" aria-label="Permalink to &quot;如果它不是一个错误,你什么也没学到&quot;">​</a></h3><p>我做过的最好的决定,是大多数人认为愚蠢的那些。</p><p>我擅长犯下巨大的错误,因为我已经意识到,那正是通向巨大成长的途径。</p><p>2018年,我刷爆了自己的第一张信用卡,试图让一门生意运转起来。</p><p>2019年,我扔掉了自己拥有的一切(除了一袋衣服和我的笔记本电脑),飞往了另一个国家。</p><p>2020年,我签了一份房租是我承受能力两倍的公寓租约。这逼着我必须让自己的生意运转起来。</p><p>关键在于:</p><p>这些事一开始都不是错误。它们始于风险。那份风险的代价就是错误,因为如果那份风险只带来了成功,你什么也学不到,也就无法复制它。</p><p>为什么这样有效?</p><p><strong>原因一</strong></p><p>金鱼会长到与它所处水缸相匹配的大小。</p><p>但如果你把它们养在一个小鱼缸里,它们永远不会长大。</p><p>你的大脑也是如此。</p><p><strong>原因二</strong></p><p>帕金森定律:</p><p>工作会自动膨胀,直至填满你为完成它所分配的全部时间。</p><p>当你把自己扔进未知之中时,你的生存受到了威胁,你拥有的、可以用来取得成功的时间也变少了。</p><p><strong>原因三</strong></p><p>关于绕一圈回到原点的主题。</p><p>想象一条直线,一端是黑色,另一端是白色,中间是渐变过渡。</p><p>现在,把两端连接起来,让它形成一个圆。</p><p>黑与白之间会出现一次瞬间的翻转。</p><p>一个笑话,不好笑到反而变得好笑。</p><p>一个人,愚蠢到反而变得有洞察力。</p><p>一个人,痛苦到别无选择只能去寻找快乐。</p><p>这是一种普遍的模式。</p><p>利用它。</p><p>这背后的心理机制是这样的:</p><ul><li>你设定一个有挑战性的目标,内心深处知道自己能够达成它。</li><li>你设定一个真实的截止日期,从而消除干扰。</li><li>它利用你的生存本能,让你迅速学会活下去所必需的东西。</li></ul><p>所以,你该怎么做?</p><p><strong>1) 深切感受你的处境</strong></p><p>对你不想过的生活产生残酷的觉知。让你的大脑在负面情绪中沸腾。</p><p><strong>2) 跃入未知</strong></p><p>做一个愚蠢的决定。逼自己去追求那个你一直搁置的梦想。不成功便成仁。</p><p><strong>3) 像疯狂科学家一样学习和构建</strong></p><p>对压力、痛苦和不堪重负进行情感炼金术。</p><p>把一切都引导向那一个有意义的目标。</p><p>在你的大脑处于储存所有相关信息的最佳状态时,去学习和研究。</p><p>你会挺过去的。</p><p>——丹</p><hr><p><a href="/en/letters/how-to-make-the-greatest-comeback-of-your-life">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',149))])}const x=o(c,[["render",d]]);export{w as __pageData,x as default};
